/**
 * Os golpes que vêm de planilha de balanceamento, espécie por espécie. Hoje são vinte e três, mais
 * uma tabela no mesmo formato para as espécies que ganham arte depois:
 *
 *   · "Moves PokeIdle Iniciais" → `GOLPES_INICIAIS`, as últimas evoluções dos 20 iniciais — hoje vazia
 *     (Venusaur e Blastoise foram refeitos na planilha de 04-10, as nove com mega em 26-10 e as outras
 *     nove em 29-10);
 *   · "Rework Moves Pseudo Lendários Revisado" → `GOLPES_PSEUDO_LENDARIOS`, os 8 pseudo-lendários —
 *     hoje vazia (os cinco com mega foram refeitos em 26-10, e Hydreigon, Goodra e Kommo-o em 29-10);
 *   · "Moves PokeIdle (Pokemons com -10 moves)" → `GOLPES_MENOS_DE_10`, hoje só Ursaring e Stantler
 *     (Granbull, Florges, Dedenne e Alcremie, que vieram nela, foram refeitos em 13-10, o Milotic
 *     em 23-10, Ampharos e Dragalge em 26-10, e as outras 29 em 27-10);
 *   · "Move Rework PokeIdle 2026-09-20" (+ os dois reportados depois) → `GOLPES_REWORK_2026_09`,
 *     hoje só o Primeape (o Shedinja, que veio nela, foi refeito em 04-10, Butterfree e Golduck em
 *     13-10, Beedrill, Pidgeot, Clefable, Alakazam e Victreebel em 26-10, e as outras 18 — Mothim e
 *     Weavile incluídos — em 27-10);
 *   · "Iniciais Kanto Moves Atuais" → `GOLPES_PRE_EVOLUCOES_KANTO`, o primeiro estágio dos
 *     três iniciais de Kanto (Ivysaur, Charmeleon e Wartortle, que vieram nela, foram refeitos
 *     em 15-10);
 *   · "Rework Moveset 28-09" → `GOLPES_REWORK_2026_09_28` — hoje vazia (Lucario e Camerupt foram
 *     refeitos em 26-10, e Electivire, Mr. Mime e Drifblim em 27-10);
 *   · "Eeveelutions 03-10" e as comuns da "Megas 03-10" → `GOLPES_REWORK_2026_10_03`, hoje Jolteon,
 *     Espeon e Leafeon (o Sylveon foi refeito em 13-10; Gengar, Scizor, Skarmory, Gardevoir e
 *     Chandelure, que vieram na das megas, em 26-10; Vaporeon, Flareon, Umbreon e Glaceon em 29-10);
 *   · "Megas 03-10" → `GOLPES_MEGAS_2026_10_03`, o moveset próprio de 45 megas — hoje vazia: a Aggron
 *     foi refeita em 21-10 e as outras 44 em 26-10. Esta não entra em `TABELAS`: quem a lê é
 *     `criarEspeciesMega` (ver o cabeçalho dela);
 *   · "Moveset Rework 04-10 - Iniciais + buff em pokemons horríveis" → `GOLPES_REWORK_2026_10_04`,
 *     Jynx e Shedinja (Venusaur e Blastoise, que vieram nela, foram refeitos em 26-10, e o Marowak
 *     em 27-10);
 *   · "Moveset Lendários" → `GOLPES_LENDARIOS_2026_10_11` — hoje vazia (a Meloetta, fora do jogo,
 *     ficou de fora, 26 foram refeitos em 27-10 e os outros 16 em 29-10, o trio do lago a pedido do dono);
 *   · "rewortk moveset pokeidle 13-10" → `GOLPES_REWORK_2026_10_13`, hoje 12 espécies do dex
 *     nacional, e `GOLPES_OUTLAND_2026_10_13`, a lista PRÓPRIA de 3 variantes Outland — esta
 *     também não entra em `TABELAS`: quem a lê é `herdarBaseOutland` (ver o cabeçalho dela).
 *     Magneton, Seadra e Roselia, e as variantes Magnetic Electabuzz, Heavy Piloswine e Furious
 *     Magmar, que vieram nela, foram refeitas em 15-10, as onze com mega em 26-10, e 134 espécies e
 *     16 variantes em 27-10;
 *   · "rhyperior_moveset" (15-10) → `GOLPES_REWORK_2026_10_15`, o Rhyperior — hoje vazia (refeito em
 *     27-10);
 *   · "Rework Moveset 2ª evo" (15-10) → `GOLPES_SEGUNDA_EVO_2026_10_15`, 85 formas do meio da
 *     cadeia (a Floette foi refeita em 26-10), e `GOLPES_OUTLAND_2026_10_15`, 5 variantes Outland —
 *     as duas de lista FECHADA (um golpe de 600 só; ver o cabeçalho da primeira);
 *   · `GOLPES_ARTE_NOVA`, sem planilha: as espécies que estavam no catálogo com `looktype: 1`
 *     e entram no jogo quando a sprite chega ao Pokedex Backup — hoje vazia (o Mimikyu, o único
 *     que passou por ela, foi refeito em 13-10);
 *   · o contrato de sprites (16-10), sem planilha → `GOLPES_CONTRATO_2026_10_16`, as nacionais que
 *     ganharam arte e as formas, de lista FECHADA (as seis com mega foram refeitas em 26-10, 224 em
 *     27-10 e 30 em 29-10: ficam 116), e `GOLPES_MEGAS_CONTRATO_2026_10_16`, as megas novas — hoje
 *     vazia (as 12 de lendário foram refeitas em 27-10, e a Mega Mewtwo Y em 29-10); esta, como a
 *     "Megas 03-10", lida por `criarEspeciesMega`;
 *   · "Novas Megas Arrumadas" (21-10) → `GOLPES_MEGAS_2026_10_21`, Mega Lucario Z, Mega Charizard X
 *     e Mega Aggron, refeitas — hoje vazia (as três foram refeitas de novo em 22-10 e 26-10);
 *   · "Mega Charizard X" (22-10) → `GOLPES_MEGAS_2026_10_22`, a correção do moveset da Mega Charizard
 *     X, que saiu da de 21-10 — hoje vazia (refeita de novo em 26-10);
 *   · "Mega Dragonite - Mega Raichu X - Milotic" (23-10) → `GOLPES_REWORK_2026_10_23`, o Milotic, e
 *     `GOLPES_MEGAS_2026_10_23`, Mega Dragonite e Mega Raichu X — hoje vazia (as duas foram refeitas
 *     de novo em 26-10);
 *   · "Rework Megas + Respectivos Pokemons 26-10" (26-10), do CEO de Moves → `GOLPES_REWORK_2026_10_26`,
 *     as 76 espécies que têm mega (hoje 68: oito foram refeitas em 27-10), e `GOLPES_MEGAS_2026_10_26`,
 *     as 52 megas de lista própria — hoje vazia (seis foram refeitas em 27-10 e as outras 46 em 29-10);
 *   · "Rework Moveset 27-10" (27-10), do CEO de Moves → `GOLPES_REWORK_2026_10_27`, 351 espécies sem
 *     mega (regionais e formas incluídas; hoje 329: 22 foram refeitas em 29-10), e
 *     `GOLPES_OUTLAND_2026_10_27`, 16 variantes Outland — esta lida por `herdarBaseOutland` antes das de
 *     15-10 e 13-10;
 *   · "Alteração Lendários + Outros 27-10" (27-10), do CEO de Moves → `GOLPES_LENDARIOS_2026_10_27`, 83
 *     lendários e míticos e oito espécies com mega que caem na regra do híbrido (hoje nove: 84 foram
 *     refeitas em 29-10), e `GOLPES_MEGAS_2026_10_27`, 18 megas — hoje vazia (refeitas em 29-10);
 *   · "Pokes Comuns Categorizados" (29-10), do CEO de Moves, e as espécies da "Mega -1 Move" (29-10) →
 *     `GOLPES_REWORK_2026_10_29`, 39 espécies sem mega e cinco com mega que mudaram;
 *   · "Lendários -1 Move" (29-10), do CEO de Moves → `GOLPES_LENDARIOS_2026_10_29`, 121 lendários e
 *     míticos — e Uxie, Mesprit e Azelf, a pedido do dono —, com um golpe de 600 a menos: ficam TRÊS;
 *   · as megas da "Mega -1 Move" e da "Lendários -1 Move" (29-10) → `GOLPES_MEGAS_2026_10_29`, as 93
 *     megas do jogo, todas SEM o golpe de mega — esta lida antes de todas por `criarEspeciesMega`.
 *
 * Mora em código, e não editado direto no JSON, pelo mesmo motivo do `AJUSTE_HUNT_LEVEL`:
 * Kanto/Johto/Hoenn vêm de `creatures-audit-overrides.json` (gerado por
 * `tools/pokedb-stats-audit/merge.mjs`) e Sinnoh+ de `creatures-novos.json` (gerado por
 * `tools/gerar-creatures-novos.py`) — rodar qualquer um dos dois de novo apagaria a edição.
 *
 * Aplicado DEPOIS dos overrides e ANTES de `herdarBaseOutland`, nas duas pontas (`content.mjs`
 * e `carregarCatalogoEspecies`): é o que faz o Brave Blastoise sair com os golpes do Blastoise,
 * e o Brave Tyranitar com os do Tyranitar.
 *
 * A planilha dos iniciais repetia nome com poder diferente em três lugares (Magical Leaf 25/60
 * em Meganium e Sceptile, Fissure 50/120 em Swampert). O cooldown é guardado pelo NOME
 * (`cdGolpes[g.name]`), então o mais fraco nunca sairia: virou Absorb / Bulldoze, com o mesmo
 * tipo, categoria e poder da linha original. (As três foram refeitas em 26-10, sem nome repetido.)
 *
 * Os golpes de 600 levam `categoriaFixa`: a planilha escolhe a categoria de cada um, e sem a
 * marca `injetarGolpesEspeciais` trocaria pela do lado de ataque mais forte da espécie.
 *
 * Linha: [nome, tipo, categoria, poder]. O cooldown não mora aqui: sai do poder pela curva de
 * `cooldown-golpes.mjs`, a mesma do resto do catálogo — mexer na curva vale para estes também.
 * A única exceção era o golpe de mega, marcado com `MEGA` na tabela das megas; desde as planilhas de
 * 29-10 nenhuma mega tem golpe de mega, e nenhuma linha com a marca sobrou.
 */
import { cooldownDoPoder, COOLDOWN_MEGA_MS } from './cooldown-golpes.mjs';

/**
 * As últimas evoluções dos iniciais — a planilha "Moves PokeIdle Iniciais". Venusaur e Blastoise
 * saíram daqui para `GOLPES_REWORK_2026_10_04`, que refez o moveset dos dois, e as nove que têm
 * mega (Charizard, Meganium, Feraligatr, Sceptile, Blaziken, Swampert, Emboar, Chesnaught e
 * Delphox) para `GOLPES_REWORK_2026_10_26`, a planilha das megas e das espécies delas: ficavam nove.
 * Em 29/10/2026 o CEO de Moves refez as nove na "Pokes Comuns Categorizados" (Typhlosion, Torterra,
 * Infernape, Empoleon, Serperior, Samurott, Incineroar, Primarina e Cinderace), e elas saíram para
 * `GOLPES_REWORK_2026_10_29`: hoje vazia.
 */
export const GOLPES_INICIAIS = {};

