/**
 * O rework de setembro de 2026 — a planilha "Move Rework PokeIdle 2026-09-20": as 24 últimas
 * evoluções de Kanto que ainda saíam com os golpes do espelho, mais o Shedinja (o único com 13
 * golpes; os outros 24 têm 11). Mothim e Weavile vieram na planilha seguinte, dos dois que
 * ficaram de fora e foram reportados depois — mesmo formato, mesma leva, mesma tabela.
 *
 * O Shedinja saiu daqui para `GOLPES_REWORK_2026_10_04`, e Butterfree e Golduck para
 * `GOLPES_REWORK_2026_10_13` — as duas planilhas refizeram o moveset deles. Beedrill, Pidgeot,
 * Clefable, Alakazam e Victreebel, que têm mega, saíram em 26/10/2026 para
 * `GOLPES_REWORK_2026_10_26`. As 299 linhas citadas abaixo contam com as 13 do Shedinja, as 22 de
 * Butterfree e Golduck e as 55 dos cinco de 26-10. Em 27/10/2026 as outras 18 (Mothim e Weavile
 * incluídos) foram refeitas na "Rework Moveset 27-10" e saíram para `GOLPES_REWORK_2026_10_27`: fica o
 * Primeape.
 *
 * Todas já são elegíveis ao golpe de assinatura, e a planilha já dá os DOIS de 600 que
 * `injetarGolpesEspeciais` exigiria — um por tipo nas de tipo duplo, dois do mesmo tipo nas de
 * tipo único —, então a injeção não acrescenta um terceiro.
 *
 * Ficam de fora, como o Sceptile #13254 ficou na planilha dos iniciais: o clone de Orre do
 * Shedinja (#13292) e o Mega Alakazam (#14065), que guardam os golpes próprios. As variantes
 * Outland (Brave Nidoking, Furious Pidgeot, Hard Golem…) herdam estes em `herdarBaseOutland`,
 * que roda depois.
 *
 * As 299 linhas batem na curva de `cooldown-golpes.mjs` com UMA exceção: o Bug Bite do Venomoth,
 * 75 de poder com 23,4s na planilha (a curva dá 24,1s; 23,4s seria poder 72). Vale a coluna de
 * PODER, que é a única que o jogo lê — o cooldown sempre sai da curva.
 */
