/**
 * A planilha "Rework Moveset 28-09": Electivire, Lucario, Mr. Mime, Drifblim e Camerupt, 11
 * golpes cada. As cinco são última evolução e a planilha já dá os dois de 600 (um por tipo; os
 * dois de ELECTRIC no Electivire, de tipo único), então a injeção não acrescenta nada.
 *
 * A planilha repetia nome com poder diferente em duas espécies — Night Shade 40/100 no
 * Drifblim, Fissure 55/120 no Camerupt. Como no Swampert dos iniciais, o de poder MENOR trocou
 * de nome e manteve tipo, categoria e poder da linha: Ominous Wind no Drifblim, Bulldoze no
 * Camerupt. Senão o `cdGolpes[g.name]` compartilharia a recarga e o mais fraco nunca sairia.
 *
 * Herdam estes sem entrada própria: os clones de Orre (#13323 Camerupt, #13448 Lucario), em
 * `herdarGolpesOrre`, e as megas (#3323 Mega Camerupt, #3448 Mega Lucario), em
 * `criarEspeciesMega`, que copia a lista da base e soma o golpe de mega. Só o Mega Lucario
 * antigo do espelho (#14448) fica com os golpes próprios, como toda a faixa 14xxx.
 *
 * Lucario e Camerupt, que têm mega, saíram daqui em 26/10/2026 para `GOLPES_REWORK_2026_10_26`
 * (a lista nova do Camerupt não tem mais Fissure nem Bulldoze); ficam Electivire, Mr. Mime e
 * Drifblim. Os clones de Orre e as megas dos dois continuam herdando, agora da lista nova. Os três que
 * ficaram foram refeitos na "Rework Moveset 27-10" (27/10/2026) e saíram para
 * `GOLPES_REWORK_2026_10_27`: a tabela fica vazia, como registro.
 *
 * As 55 linhas batem na curva de `cooldown-golpes.mjs` no décimo, sem exceção; a coluna
 * "ATK% / SPA%" é a razão da espécie no jogo nas cinco.
 */
export const GOLPES_REWORK_2026_09_28 = {};

