/**
 * As 16 variantes Outland da "Rework Moveset 27-10", cada uma com a lista PRÓPRIA, na coluna ao lado da
 * base. A chave é o pokeId da variante (#2001+). As 16 saíram de `GOLPES_OUTLAND_2026_10_13`, onde ficam
 * Furious Scyther, Enigmatic Girafarig e Brute Rhydon.
 *
 * Em 13 a lista é OUTRA que a da base — Charged Raichu, Furious Gyarados e Brave Steelix contra a base que a
 * planilha só repetiu, de referência; as outras dez contra a base refeita na mesma planilha. Ancient Hypno,
 * Ancient Granbull e Banshee Mismagius vieram iguais à base refeita e moram aqui também, para a variante
 * não mudar sozinha numa planilha futura da base.
 *
 * Mesma leitura da de 13-10: NÃO entra em `TABELAS` (`aplicarGolpesDasPlanilhas` roda antes de
 * `herdarBaseOutland`, que sobrescreveria a lista) — quem a lê é o próprio `herdarBaseOutland`, por
 * `golpesDaPlanilhaDoOutland`, que olha esta antes das de 15-10 e 13-10. Com dois 600 por variante, um por
 * tipo, `injetarGolpesEspeciais` não acrescenta nada.
 */
