/**
 * As megas das planilhas "Mega -1 Move" e "Lendários -1 Move" do CEO de Moves (29/10/2026): as 93 megas do jogo, na
 * coluna ao lado da espécie — as 13 de lendário na segunda e as outras 80 na primeira. Mesmo formato das outras
 * tabelas de mega, lida por `golpesDaPlanilhaDaMega` antes de todas.
 *
 * As duas planilhas TIRAM o golpe de mega de todas: "sai o golpe de mega: as megas ficam só com os golpes de 600
 * comuns". A mega fica com DOIS de 600 (um por tipo nas de tipo duplo, dois do tipo nas de tipo único) e a de
 * lendário com TRÊS, como o lendário — todos com os 60 s da curva; nenhuma linha leva a marca `MEGA`. Em 70 das 80
 * e nas 13 de lendário a lista é a de antes sem o golpe de mega (nas de lendário de tipo duplo, como o golpe de mega
 * era do primário, sobram dois 600 do secundário e um do primário). As outras dez também refazem a categoria, pela
 * régua do híbrido ou da categoria única com os números DA MEGA: Mega Blastoise, Victreebel, Starmie, Dragonite,
 * Blaziken, Camerupt, Garchomp Z, Lucario, Eelektross e Malamar. Em duas linhas a planilha trocou só a categoria e
 * marcou "revisar" (o Draconic Soul físico na Mega Dragonite e especial na Mega Garchomp Z) — entram como vieram.
 *
 * Saíram para cá as 46 de `GOLPES_MEGAS_2026_10_26`, as 18 de `GOLPES_MEGAS_2026_10_27` e a Mega Mewtwo Y de
 * `GOLPES_MEGAS_CONTRATO_2026_10_16` — as três ficam vazias —, e entram as 28 que eram a cópia da base mais o golpe
 * de mega (`criarEspeciesMega`): sem o golpe de mega, a cópia não é mais o que a planilha manda, e agora elas têm a
 * lista aqui — 24 iguais à da base de hoje e quatro com lista própria (Blastoise, Blaziken, Camerupt e Lucario).
 * Nenhuma mega do jogo cai mais no ramo da cópia, e nenhuma segue sozinha uma mudança futura da base.
 *
 * A coluna de cooldown segue a curva do jogo em todas as linhas. O Cinder Barrage (FIRE, especial, 100) da Mega
 * Camerupt é nome de golpe novo no catálogo.
 */
