const TABELAS = [
  GOLPES_INICIAIS,
  GOLPES_PSEUDO_LENDARIOS,
  GOLPES_MENOS_DE_10,
  GOLPES_REWORK_2026_09,
  GOLPES_PRE_EVOLUCOES_KANTO,
  GOLPES_REWORK_2026_09_28,
  GOLPES_REWORK_2026_10_03,
  GOLPES_REWORK_2026_10_04,
  GOLPES_LENDARIOS_2026_10_11,
  GOLPES_REWORK_2026_10_13,
  GOLPES_REWORK_2026_10_15,
  GOLPES_SEGUNDA_EVO_2026_10_15,
  GOLPES_ARTE_NOVA,
  GOLPES_CONTRATO_2026_10_16,
  GOLPES_REWORK_2026_10_23,
  GOLPES_REWORK_2026_10_26,
  GOLPES_REWORK_2026_10_27,
  GOLPES_LENDARIOS_2026_10_27,
  GOLPES_REWORK_2026_10_29,
  GOLPES_LENDARIOS_2026_10_29,
];

/**
 * As tabelas de lista FECHADA: a planilha dá às formas do meio UM golpe de 600, e o injetor não
 * pode completar o par em quem passa por forma final no boot (ver `GOLPES_SEGUNDA_EVO_2026_10_15`).
 * A do contrato de 16/10 também: a conta de 600 dela é a regra do dono, e não a do injetor.
 */
const TABELAS_FECHADAS = new Set([GOLPES_SEGUNDA_EVO_2026_10_15, GOLPES_CONTRATO_2026_10_16]);

/**
 * Uma linha de planilha vira golpe: liberado desde o nível 1, cooldown da curva, e a categoria
 * dos de 600 travada (`categoriaFixa`). A linha marcada `MEGA` é o golpe de mega — 30 s fora da
 * curva, com as mesmas marcas de `golpeMegaDe` (`cdFixo` segura os 30 s, `golpeMega` pinta o selo).
 * Desde as planilhas de 29-10, que tiraram o golpe de mega de todas, nenhuma linha leva a marca.
 */
function golpeDaLinha([name, type, category, power, marca]) {
  if (marca === MEGA) {
    return { name, type, category, power, cooldownMs: COOLDOWN_MEGA_MS, learnLevel: 1, categoriaFixa: true, cdFixo: true, golpeMega: true };
  }
  return {
    name,
    type,
    category,
    power,
    cooldownMs: cooldownDoPoder(power),
    learnLevel: 1,
    ...(power >= 600 ? { categoriaFixa: true } : {}),
  };
}

/**
 * Os golpes da mega nas planilhas "Mega -1 Move" e "Lendários -1 Move" (29-10), na "Alteração Lendários +
 * Outros 27-10", na "Rework Megas + Respectivos Pokemons 26-10", na "Mega Dragonite - Mega Raichu X -
 * Milotic" (23-10), na "Mega Charizard X" (22-10), na "Novas Megas Arrumadas" (21-10), na do contrato de
 * 16/10 ou na "Megas 03-10", ou `null` se ela não está em nenhuma (aí vale a cópia da base). Desde 29/10
 * só a de 29-10 tem linhas — as 93 megas do jogo, sem golpe de mega —; as outras ficaram vazias e seguem
 * na fila como registro.
 */
export function golpesDaPlanilhaDaMega(pokeId) {
  const linhas = GOLPES_MEGAS_2026_10_29[pokeId]
    ?? GOLPES_MEGAS_2026_10_27[pokeId]
    ?? GOLPES_MEGAS_2026_10_26[pokeId]
    ?? GOLPES_MEGAS_2026_10_23[pokeId]
    ?? GOLPES_MEGAS_2026_10_22[pokeId]
    ?? GOLPES_MEGAS_2026_10_21[pokeId]
    ?? GOLPES_MEGAS_CONTRATO_2026_10_16[pokeId]
    ?? GOLPES_MEGAS_2026_10_03[pokeId];
  return linhas ? linhas.map(golpeDaLinha) : null;
}

/**
 * Os golpes PRÓPRIOS da variante Outland nas planilhas de 13-10, 15-10 e 27-10, ou `null` se ela não está
 * lá (aí ela herda os da base). Quem chama é `herdarBaseOutland` — ver o cabeçalho de
 * `GOLPES_OUTLAND_2026_10_13`.
 */
export function golpesDaPlanilhaDoOutland(pokeId) {
  const linhas = GOLPES_OUTLAND_2026_10_27[pokeId] ?? GOLPES_OUTLAND_2026_10_15[pokeId] ?? GOLPES_OUTLAND_2026_10_13[pokeId];
  return linhas ? linhas.map(golpeDaLinha) : null;
}

/**
 * A variante Outland cuja lista é FECHADA (`GOLPES_OUTLAND_2026_10_15`): `herdarBaseOutland` a
 * marca com `golpesFechados`, como `aplicarGolpesDasPlanilhas` faz com as tabelas fechadas.
 */
export function golpesDoOutlandFechados(pokeId) {
  return Object.hasOwn(GOLPES_OUTLAND_2026_10_15, pokeId);
}

/**
 * Troca os golpes de cada espécie das tabelas pelos da planilha — todos liberados desde o nível 1.
 *
 * `obter` devolve TODAS as entradas com aquele pokeId, não a primeira: quatro espécies aparecem
 * DUAS vezes na lista do catálogo, uma no espelho e outra em `creatures-novos.json` (#461
 * Weavile, #468 Togekiss, #571 Zoroark, #700 Sylveon). Quem fica de pé é a última — é ela que o
 * `new Map(...)` de `especies` e o `estado.especies.set(...)` do cliente guardam —, então um
 * `find` escreveria na cópia morta e a planilha sumiria em silêncio, sem erro nenhum. Foi o que
 * aconteceu com o Weavile antes desta linha.
 *
 * A espécie de uma tabela de `TABELAS_FECHADAS` sai com `golpesFechados`: a lista é a da planilha
 * e ponto, e `injetarGolpesEspeciais` não acrescenta 600 nenhum (ver `elegivelParaGolpeEspecial`).
 */
export function aplicarGolpesDasPlanilhas(obter) {
  for (const tabela of TABELAS) {
    const fechada = TABELAS_FECHADAS.has(tabela);
    for (const [id, linhas] of Object.entries(tabela)) {
      for (const esp of obter(Number(id)) ?? []) {
        esp.attacks = linhas.map(golpeDaLinha);
        if (fechada) esp.golpesFechados = true;
        else delete esp.golpesFechados;
      }
    }
  }
}
